const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const picture=(key,alt='',cls='',eager=false)=>A[key]?.endsWith('.mp4')?`<video width="${DIM[key][0]}" height="${DIM[key][1]}" src="${esc(A[key])}" data-asset="${key}" aria-label="${esc(alt)}" class="${cls}" ${(key.startsWith('bhabha-motion-')||key.startsWith('original-'))?`poster="${A[key].replace(/\.mp4$/,'.jpg')}"`:""}  muted loop playsinline preload="none" draggable="false"></video>`:`<img width="${DIM[key][0]}" height="${DIM[key][1]}" src="${esc(A[key])}" data-asset="${key}" alt="${esc(alt)}" class="${cls}" ${eager?'fetchpriority="high"':'loading="lazy"'} decoding="async" draggable="false">`;
const link=(p,cls='')=>`<a class="${cls}" href="project/${p.id}/">${picture(p.id,p.title+' — '+p.type)}<div class="index-caption"><h2>${p.title}</h2><span>${p.category} ↗</span></div>${projectTags(p)}</a>`;
